import Ajv from 'ajv';
const ajv = new Ajv();
const messageSchema = { type: 'object', properties: { coordinator: { type: 'string' }, action: { type: 'string' } }, required: ['coordinator', 'action'] };
const validate = ajv.compile(messageSchema);

function safeParseMessage(message) {
  if (typeof message !== 'string' || message.length > 10240) {
    throw new Error('Invalid message format or size');
  }
  const parsed = JSON.parse(message);
  delete parsed.__proto__;
  delete parsed.constructor;
  if (!validate(parsed)) {
    throw new Error('Message validation failed: ' + ajv.errorsText(validate.errors));
  }
  return parsed;
}

import crypto from 'crypto';

class AuthenticatedCoordinator {
  constructor(id, secret) {
    this.id = id;
    this.secret = secret;
  }

  signMessage(message) {
    const payload = JSON.stringify(message);
    const hmac = crypto.createHmac('sha256', this.secret);
    hmac.update(payload);
    return {
      payload: message,
      signature: hmac.digest('hex'),
      timestamp: Date.now()
    };
  }

  verifyMessage(signed, expectedId) {
    if (Date.now() - signed.timestamp > 120000) {
      throw new Error('Message expired');
    }
    const hmac = crypto.createHmac('sha256', this.secret);
    hmac.update(JSON.stringify(signed.payload));
    const expectedSig = hmac.digest('hex');
    if (signed.signature !== expectedSig) {
      throw new Error('Invalid signature');
    }
    if (signed.payload.coordinator !== expectedId) {
      throw new Error('Coordinator ID mismatch');
    }
    return signed.payload;
  }
}

import Redlock from 'redlock';

class RobustCoordinator {
  constructor(redis) {
    this.redlock = new Redlock([redis], {
      driftFactor: 0.01,
      retryCount: 10,
      retryDelay: 200,
      retryJitter: 200
    });
  }

  async attemptClaim(combo) {
    const lockKey = `coordination:locks:${combo}`;
    try {
      const lock = await this.redlock.acquire([lockKey], 5000);
      try {
        // Check existing claim
        const existing = await redis.get(`coordination:claims:claimed:${combo}`);
        if (existing) {
          return false;
        }
        // Atomic claim with ownership proof
        await redis.setex(
          `coordination:claims:claimed:${combo}`,
          300,
          JSON.stringify({ coordinator: this.id, nonce: crypto.randomBytes(16).toString('hex') })
        );
        return true;
      } finally {
        await lock.release();
      }
    } catch (error) {
      console.error('Lock acquisition failed:', error);
      return false;
    }
  }
}

class RateLimitedRedis {
  constructor(redis) {
    this.redis = redis;
    this.limits = new Map(); // coordinator -> { tokens, lastRefill }
    this.maxTokens = 100;
    this.refillRate = 100 / 60; // tokens per second
  }

  async publish(channel, message, coordinatorId) {
    // Token bucket rate limiting
    const now = Date.now();
    let bucket = this.limits.get(coordinatorId) || { tokens: this.maxTokens, lastRefill: now };

    const elapsed = (now - bucket.lastRefill) / 1000;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + elapsed * this.refillRate);
    bucket.lastRefill = now;

    if (bucket.tokens < 1) {
      throw new Error('Rate limit exceeded for coordinator: ' + coordinatorId);
    }

    bucket.tokens -= 1;
    this.limits.set(coordinatorId, bucket);

    // Check queue depth
    const queueDepth = await this.redis.llen('coordination:timeline');
    if (queueDepth > 10000) {
      throw new Error('System overloaded - message queue full');
    }

    return await this.redis.publish(channel, message);
  }
}

class SecureLogger {
  constructor() {
    this.sensitiveFields = ['apiKey', 'password', 'token', 'secret', 'credential'];
  }

  redact(obj) {
    if (typeof obj !== 'object' || obj === null) return obj;
    const redacted = Array.isArray(obj) ? [] : {};
    for (const [key, value] of Object.entries(obj)) {
      if (this.sensitiveFields.some(field => key.toLowerCase().includes(field))) {
        redacted[key] = '[REDACTED]';
      } else if (typeof value === 'object') {
        redacted[key] = this.redact(value);
      } else {
        redacted[key] = value;
      }
    }
    return redacted;
  }

  info(message, data) {
    console.log(message, this.redact(data));
  }
}

class SecureErrorHandler {
  static sanitizeError(error) {
    const sanitized = {
      code: error.code || 'INTERNAL_ERROR',
      message: 'An error occurred during coordination',
      timestamp: Date.now()
    };

    // Log full details securely
    secureLogger.error('Full error details', {
      message: error.message,
      stack: error.stack,
      coordinator: this.id
    });

    return sanitized;
  }

  static handleError(error) {
    const sanitized = this.sanitizeError(error);
    console.error('Error:', sanitized.code, sanitized.message);
    return sanitized;
  }
}

class ResourceLimitedCoordinator {
  constructor(id, redis, limits) {
    this.limits = {
      maxAgents: limits.maxAgents || 50,
      maxMemoryMB: limits.maxMemoryMB || 512,
      maxCPUPercent: limits.maxCPUPercent || 80
    };
  }

  async spawnAgent(combo) {
    // Check global limit
    const currentCount = await this.redis.hlen('coordination:agents:active');
    if (currentCount >= this.limits.maxAgents) {
      throw new Error('Global agent limit reached');
    }

    // Check coordinator-specific quota
    const coordAgents = await this.redis.hget(
      `coordination:coordinator:${this.id}`,
      'agentCount'
    );
    if (parseInt(coordAgents || 0) >= this.limits.maxAgents) {
      throw new Error('Coordinator agent quota exceeded');
    }

    return await super.spawnAgent(combo);
  }
}

class IntegrityProtectedMessage {
  constructor(secret) {
    this.secret = secret;
    this.sequenceNumber = 0;
  }

  createMessage(payload) {
    const message = {
      payload,
      sequence: ++this.sequenceNumber,
      nonce: crypto.randomBytes(16).toString('hex'),
      timestamp: Date.now()
    };

    const hmac = crypto.createHmac('sha256', this.secret);
    hmac.update(JSON.stringify(message));
    message.signature = hmac.digest('hex');

    return message;
  }

  verifyMessage(message, expectedSequence) {
    const { signature, ...data } = message;
    const hmac = crypto.createHmac('sha256', this.secret);
    hmac.update(JSON.stringify(data));
    const expectedSig = hmac.digest('hex');

    if (signature !== expectedSig) {
      throw new Error('Message signature invalid');
    }
    if (message.sequence <= expectedSequence) {
      throw new Error('Message replay detected');
    }
    if (Date.now() - message.timestamp > 300000) {
      throw new Error('Message expired');
    }

    return message.payload;
  }
}

class SecurityAuditLogger {
  constructor(redis) {
    this.redis = redis;
  }

  async logSecurityEvent(event) {
    const auditEntry = {
      eventType: event.type,
      severity: event.severity,
      coordinator: event.coordinator,
      action: event.action,
      result: event.result,
      correlationId: event.correlationId || crypto.randomUUID(),
      timestamp: Date.now(),
      metadata: event.metadata
    };

    // Immutable append-only log
    await this.redis.xadd(
      'coordination:security:audit',
      '*',
      'event', JSON.stringify(auditEntry)
    );

    // Alert on critical events
    if (event.severity === 'CRITICAL') {
      await this.redis.publish('security:alerts', JSON.stringify(auditEntry));
    }
  }

  async logAuthAttempt(coordinator, success, reason) {
    await this.logSecurityEvent({
      type: 'AUTHENTICATION',
      severity: success ? 'INFO' : 'WARNING',
      coordinator,
      action: 'COORDINATOR_AUTH',
      result: success ? 'SUCCESS' : 'FAILURE',
      metadata: { reason }
    });
  }
}
